const out = [];
const skipped = [];
let first = true;
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    if (/html/i.test(p.name || '')) { skipped.push(p.name); continue; }
    out.push({ json: {
      project_id: p.project_id,
      project_name: p.name,
      base_lang: (p.base_language_iso || 'en').toLowerCase(),
      qa_type: 'spelling_and_grammar',
      qa_label: 'Typos'
    }});
    if (first) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: 'en',
        qa_type: '__control_invalid__',
        qa_label: '__CONTROL__'
      }});
      first = false;
    }
  }
}
for (const o of out) { o.json.skipped_html = skipped; }
return out;

const MAX_PAGES = 30;
const PER = 500;
const reqs = $('Build Count Requests').all();
const res = $input.all();
const out = [];
const failed = [];
const capped = [];
let controlStatus = null;
let scanned = 0;
let skippedHtml = [];

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (meta.skipped_html && meta.skipped_html.length > skippedHtml.length) { skippedHtml = meta.skipped_html; }

  const r = res[i].json || {};
  const hdr = r.headers || {};
  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }

  scanned++;
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name); continue; }
  if (total === 0) { continue; }

  let pages = Math.ceil(total / PER);
  if (pages > MAX_PAGES) { pages = MAX_PAGES; capped.push(meta.project_name); }
  for (let p = 1; p <= pages; p++) {
    out.push({ json: {
      project_id: meta.project_id,
      project_name: meta.project_name,
      base_lang: meta.base_lang,
      page: p,
      pages: pages,
      flagged_total: total
    }});
  }
}

for (const o of out) {
  o.json.scanned = scanned;
  o.json.failed = failed;
  o.json.capped = capped;
  o.json.control_status = controlStatus;
  o.json.skipped_html = skippedHtml;
}
if (out.length === 0) {
  out.push({ json: { project_id: null, project_name: null, base_lang: 'en', page: 0, pages: 0, flagged_total: 0, scanned: scanned, failed: failed, capped: capped, control_status: controlStatus, skipped_html: skippedHtml } });
}
return out;

const pageMeta = $('Build Page Requests').all();
const meta0 = (pageMeta[0] || { json: {} }).json;
const res = $input.all();
const rows = [];
const seen = {};
const readFail = [];
let keysExamined = 0;

for (const it of res) {
  const j = it.json || {};
  if (!j.project_id) { continue; }
  if (!j.ok) { readFail.push(String(j.project) + ' p' + String(j.page)); continue; }
  keysExamined += (j.keys_examined || 0);
  for (const r of (j.rows || [])) {
    const sig = r.project_id + '#' + r.key_id + '#' + r.lang + '#' + r.rule + '#' + r.token;
    if (seen[sig]) { continue; }
    seen[sig] = 1;
    rows.push(r);
  }
}

const byProject = {};
const projIds = {};
const byRule = {};
const byLang = {};
for (const row of rows) {
  if (!byProject[row.project]) { byProject[row.project] = {}; }
  if (!byProject[row.project][row.lang]) { byProject[row.project][row.lang] = 0; }
  byProject[row.project][row.lang]++;
  projIds[row.project] = row.project_id;
  byRule[row.rule] = (byRule[row.rule] || 0) + 1;
  byLang[row.lang] = (byLang[row.lang] || 0) + 1;
}

const names = Object.keys(byProject);
names.sort(function (a, b) { return a.replace(/^[^A-Za-z0-9]+/, '').toLowerCase().localeCompare(b.replace(/^[^A-Za-z0-9]+/, '').toLowerCase()); });

const failed = (meta0.failed || []).concat(readFail);
const capped = meta0.capped || [];
const controlStatus = meta0.control_status;

let msg = '*Lokalise nightly QA — typos in target languages*\n\n';
if (names.length === 0) {
  msg += ':white_check_mark: No high-confidence typos found.\n';
} else {
  msg += '*Total:* ' + rows.length + ' in ' + names.length + ' project(s)\n\n';
  for (const n of names) {
    const label = String(n).replace(/[<>|]/g, ' ').trim();
    msg += '<https://app.lokalise.com/project/' + projIds[n] + '/|' + label + '>\n';
    const isos = Object.keys(byProject[n]);
    isos.sort();
    for (const iso of isos) { msg += '    • ' + iso + ': ' + byProject[n][iso] + '\n'; }
    msg += '\n';
  }
}
if (failed.length > 0) { msg += '\n:warning: could not read: ' + failed.join(', '); }
if (capped.length > 0) { msg += '\n:warning: page cap reached, count is a floor: ' + capped.join(', '); }
if (controlStatus !== 400) { msg += '\n:rotating_light: control probe returned ' + controlStatus + ' instead of 400 — treat these numbers as unverified.'; }
if (msg.length > 3800) { msg = msg.slice(0, 3760) + '\n… truncated'; }

return [{ json: {
  typo_message: msg,
  typo_total: rows.length,
  projects_with_typos: names.length,
  projects_scanned: meta0.scanned || 0,
  keys_examined: keysExamined,
  by_project: byProject,
  by_lang: byLang,
  by_rule: byRule,
  skipped_html: meta0.skipped_html || [],
  failed: failed,
  capped: capped,
  control_status: controlStatus,
  rows: rows
}}];
